#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double a[3][3]={{1,2,3},{2,4,6},{1,1,1}};
    int rank=0;
    for (int col=0;col<3;col++){
        int pivot=-1;
        for (int i=rank;i<3;i++)if (fabs(a[i][col])>1e-10){
            pivot=i;
            break;
        }
        if (pivot<0)continue;
        for (int j=col;j<3;j++)swap(a[pivot][j],a[rank][j]);
        double p=a[rank][col];
        for (int j=col;j<3;j++)a[rank][j]/=p;
        for (int i=0;i<3;i++)if (i!=rank){
            double factor=a[i][col];
            for (int j=col;j<3;j++)a[i][j]-=factor*a[rank][j];
        }
        rank++;
    }
    cout<<rank<<"\n";
    return 0;
}

