#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<double>a={1,2,2},b={2,1,3};
    double n=0;
    for (double x:a)n+=x*x;
    n=sqrt(n);
    for (double& x:a)x/=n;
    double dot=0;
    for (int i=0;i<3;i++)dot+=a[i]*b[i];
    for (int i=0;i<3;i++)b[i]-=dot*a[i];
    n=0;
    for (double x:b)n+=x*x;
    n=sqrt(n);
    for (double& x:b)x/=n;
    double check=0;
    for (int i=0;i<3;i++)check+=a[i]*b[i];
    cout<<fixed<<setprecision(8)<<check<<"\n";
    return 0;
}

