#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<double>target={1,2,3,4,5},featureA={1,2,3,4,5},featureB={2,1,3,1,2};
    for (const auto& x:{
        featureA,featureB
    }
    ){
        double mx=0,my=0,num=0,xx=0,yy=0;
        for (int i=0;i<5;i++){
            mx+=x[i]/5;
            my+=target[i]/5;
        }
        for (int i=0;i<5;i++){
            double a=x[i]-mx,b=target[i]-my;
            num+=a*b;
            xx+=a*a;
            yy+=b*b;
        }
        cout<<(xx*yy>0?num/sqrt(xx*yy):0)<<"\n";
    }
    return 0;
}

