int main(){
    vector<double>x={1,2,3,4},u={0.1,-0.3,0.2,-0.2};
    double xx=0,meat=0;
    for (int i=0;i<4;i++){
        xx+=x[i]*x[i];
        meat+=x[i]*x[i]*u[i]*u[i];
    }
    double robustVariance=meat/(xx*xx);
    cout<<fixed<<setprecision(8)<<robustVariance<<"\n";
    return 0;
}
